EDGES = (
 '  - {from: firstfruits_ebal_curses, to: family, disposition: FALSE, link: none,\n'
 f'     why: "{M} | 26:1 \'when you come into the land which the LORD your God gives you FOR AN INHERITANCE (נחלה — inheritance) and possess it\' — THE GIFT FORMULA\'S noun, the land given to the nation, not an heir\'s share: 13b\'s list of the formula\'s seats computed by lemma on Data/tanakh.sqlite names 26:1 itself (release_firstborn -> family FALSE, its why); the first-fruits line reads 26:1 as its condition (the basket at the place); 12b\'s and 7b\'s precedent too; no link (a homograph); filed from the gate\'s first print (FAIL EDGE -> family [inheritance] at Deut 26:1)"}}\n'
 '  - {from: firstfruits_ebal_curses, to: lev24, disposition: FALSE, link: none,\n'
 f'     why: "{M} | 28:47 \'BECAUSE (תחת אשר — because) you did not serve the LORD your God with joy\' and 28:62 \'BECAUSE you did not obey the voice of the LORD your God\' — the conjunction \'because\' twice inside the curse arm\'s causal clauses, never the talion formula\'s \'eye FOR eye\' (Leviticus 24:20 — the lev24 runner\'s law); 2b\'s precedent (naso -> lev24 FALSE, the preposition \'under\' four times); no link (a homograph); filed from the gate\'s first print (FAIL EDGE -> lev24 [talion_formula] at Deut 28:47, Deut 28:62)"}}\n'
 '  - {from: firstfruits_ebal_curses, to: offerings, disposition: VIA, link: reference, via: korach,\n'
 f'     why: "{M} | 27:7 \'and you shall sacrifice peace-offerings (שלמים — peace offerings) and eat there and rejoice before the LORD your God\' — the Ebal altar\'s peace-offerings; the runner reaches the offerings runner\'s peace-offering law THROUGH korach (cold_run_korach.py imports cold_run_offerings as OF — verified at its line 38; korach -> offerings CALL, reference on file), whose gifts cell the runner calls for the first fruits (KO); 27:7 the source seat of rejoicing (the rejoicing effect\'s fourth seat amended at the types); 13b\'s precedent for the VIA form (release_firstborn -> pesach VIA korach); filed from the gate\'s first print (FAIL EDGE -> offerings [shelamim] at Deut 27:7)"}}\n'
 '  - {from: firstfruits_ebal_curses, to: temurah, disposition: VIA, link: reference, via: food_tithe,\n'
 f'     why: "{M} | 26:12 \'when you have finished tithing all the tithe of your produce in the third year, the year of the tithe\' — the tithe\'s token: the tithe\'s redemption and its added fifth the temurah runner\'s (Leviticus 27:30-31), reached THROUGH food_tithe (cold_run_food_tithe.py imports cold_run_temurah as TM — verified at its line 42), whose removal and confession cells the runner calls (FT); filed from the gate\'s first print (FAIL EDGE -> temurah [tithe] at Deut 26:12)"}}\n'
 '  - {from: firstfruits_ebal_curses, to: yovel, disposition: VIA, link: reference, via: food_tithe,\n'
 f'     why: "{M} | 26:12 the same seat — the tithe\'s cycle of years (the third and the sixth the poor tithe\'s; the seventh no tithe) the yovel runner\'s count (Leviticus 25), reached THROUGH food_tithe (cold_run_food_tithe.py imports cold_run_yovel as YO — verified at its line 44); the removal date the calendar\'s the_removal_date parameter, exercised by both runners since the types; filed from the gate\'s first print (FAIL EDGE -> yovel [tithe] at Deut 26:12)"}}\n')
